function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 100000) return 'The tree has at most 10^5 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 9)) return 'Every node value is a digit from 1 to 9.';
  // Each present node owns the next two entries; anything left over has no parent.
  let nodes = 1;
  let next = 1;
  for (let done = 0; done < nodes && next < root.length; done++) {
    for (let side = 0; side < 2 && next < root.length; side++) if (root[next++] !== null) nodes++;
  }
  if (next < root.length) return 'Some values in the level-order list have no parent.';
  return null;
}

