function pseudoPalindromicPaths(root) {
  function dfs(node, parity) {
    if (node === null) {
      return 0;
    }
    const mask = parity ^ (1 << node.val);
    if (node.left === null && node.right === null) {
      return (mask & (mask - 1)) === 0 ? 1 : 0;
    }
    return dfs(node.left, mask) + dfs(node.right, mask);
  }
  return dfs(root, 0);
}

