function pseudoPalindromicPaths(root) {
  // List every root-to-leaf path's values, then count how many digits occur an odd number of times.
  let count = 0;
  const stack = [[root, []]];
  while (stack.length) {
    const [node, above] = stack.pop();
    const values = above.concat([node.val]);
    if (!node.left && !node.right) {
      const freq = new Array(10).fill(0);
      for (const v of values) freq[v]++;
      if (freq.filter(f => f % 2 === 1).length <= 1) count++;
      continue;
    }
    if (node.left) stack.push([node.left, values]);
    if (node.right) stack.push([node.right, values]);
  }
  return count;
}

